warnings.simplefilter('ignore')
HEAD = "import numpy as np\nimport matplotlib.pyplot as plt\n"
out = []
for c in CASES:
    plt.close('all')
    plt.rcdefaults()
    buf = io.StringIO()
    try:
        with contextlib.redirect_stdout(buf):
            exec(HEAD + c, {})
        res = buf.getvalue()
    except Exception as e:
        msg = repr(e.args[0]) if type(e).__name__ == 'KeyError' else str(e)
        res = f'{buf.getvalue()}{type(e).__name__}: {msg}'
    out.append([c, re.sub(r'0x[0-9a-f]+', '0x', res)])
path = pathlib.Path(__file__).parent.parent / 'src/lib/pyPlotCases.json'
path.write_text(json.dumps(out, ensure_ascii=False, indent=0) + '\n')
print(f'{len(out)} snippets on matplotlib {matplotlib.__version__}')
